SELECT product_id, CASE WHEN units >= 33 THEN 'high' WHEN units >= 18 THEN 'mid' ELSE 'low' END AS units_bucket, COUNT(revenue) AS revenue_count, ROUND(STDDEV(revenue), 2) AS stddev_revenue FROM store_sales WHERE store_id IN (2, 3, 6) GROUP BY product_id, CASE WHEN units >= 33 THEN 'high' WHEN units >= 18 THEN 'mid' ELSE 'low' END HAVING COUNT(revenue) >= 3 ORDER BY product_id DESC;
